import { useEffect, useRef, useState } from "react";

import { terminalHostManager, type TerminalInstance } from "../lib/terminalHostManager";
import { useTerminalSettings } from "../lib/terminalSettings";
import type { TerminalSession } from "../lib/types";
import { TerminalSearchOverlay } from "./TerminalSearchOverlay";

type TerminalPaneProps = {
  session: TerminalSession;
  active: boolean;
  onBell?: () => void;
  onTitleChange?: (title: string) => void;
  searchOpen?: boolean;
  onCloseSearch?: () => void;
};

function fitMountedTerminal(container: HTMLDivElement, instance: TerminalInstance) {
  if (!container.isConnected || !container.contains(instance.element)) return false;
  const rect = container.getBoundingClientRect();
  if (rect.width <= 0 || rect.height <= 0) return false;

  Object.assign(instance.element.style, {
    position: "absolute",
    inset: "0px",
    width: "100%",
    height: "100%",
    minWidth: "0px",
    minHeight: "0px",
    overflow: "hidden",
  });
  instance.fitAddon.fit();
  return true;
}

export function TerminalPane({ session, active, onBell, onTitleChange, searchOpen, onCloseSearch }: TerminalPaneProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [error, setError] = useState<string | null>(null);
  const { settings } = useTerminalSettings();

  useEffect(() => {
    terminalHostManager.applySettings(settings);
  }, [settings]);

  useEffect(() => {
    terminalHostManager.updateSession(session.id, session);
  }, [session]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    let cancelled = false;
    let firstFitFrame = 0;
    let secondFitFrame = 0;
    let resizeObserver: ResizeObserver | null = null;

    const cancelScheduledFit = () => {
      if (firstFitFrame) cancelAnimationFrame(firstFitFrame);
      if (secondFitFrame) cancelAnimationFrame(secondFitFrame);
      firstFitFrame = 0;
      secondFitFrame = 0;
    };

    const scheduleStableFit = (instance: TerminalInstance, focus = false) => {
      cancelScheduledFit();
      firstFitFrame = requestAnimationFrame(() => {
        firstFitFrame = 0;
        if (cancelled) return;
        const fitted = fitMountedTerminal(container, instance);
        if (focus && fitted) instance.terminal.focus();
        secondFitFrame = requestAnimationFrame(() => {
          secondFitFrame = 0;
          if (cancelled) return;
          fitMountedTerminal(container, instance);
        });
      });
    };

    void terminalHostManager
      .getOrCreate(session, active, onBell, onTitleChange)
      .then((instance) => {
        if (cancelled) return;
        if (!container.contains(instance.element)) {
          container.replaceChildren(instance.element);
        }

        resizeObserver = new ResizeObserver(() => scheduleStableFit(instance));
        resizeObserver.observe(container);
        scheduleStableFit(instance, active);

        const fontsReady = typeof document !== "undefined" ? document.fonts?.ready : undefined;
        void fontsReady?.then(() => {
          if (!cancelled) scheduleStableFit(instance);
        });
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : "Failed to mount terminal");
      });

    return () => {
      cancelled = true;
      resizeObserver?.disconnect();
      cancelScheduledFit();
    };
  }, [session.id]);

  useEffect(() => {
    const instance = terminalHostManager.getInstance(session.id);
    const container = containerRef.current;
    if (instance) {
      instance.active = active;
      if (active && container) {
        requestAnimationFrame(() => {
          if (fitMountedTerminal(container, instance)) instance.terminal.focus();
        });
      }
    }
  }, [active, session.id]);

  return (
    <div
      data-testid="terminal-pane-surface"
      className="relative h-full w-full min-h-0 min-w-0 overflow-hidden"
      style={{ backgroundColor: settings.theme.background }}
    >
      <div
        ref={containerRef}
        data-testid="terminal-mount"
        className="relative h-full w-full min-h-0 min-w-0 overflow-hidden"
        style={{ backgroundColor: settings.theme.background }}
      />
      {searchOpen ? (
        <TerminalSearchOverlay
          instance={terminalHostManager.getInstance(session.id)}
          onClose={onCloseSearch ?? (() => undefined)}
        />
      ) : null}
      {error ? (
        <div className="pointer-events-none absolute bottom-3 right-3 max-w-error rounded-md border border-destructive/30 bg-destructive/10 px-2 py-1 text-[11px] text-destructive">
          {error}
        </div>
      ) : null}
    </div>
  );
}

import { act, cleanup, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import type { TerminalSession } from "../lib/types";
import { TerminalPane } from "./TerminalPane";

const manager = vi.hoisted(() => ({
  applySettings: vi.fn(),
  updateSession: vi.fn(),
  getOrCreate: vi.fn(),
  getInstance: vi.fn(),
}));

vi.mock("../lib/terminalHostManager", () => ({ terminalHostManager: manager }));
vi.mock("../lib/terminalSettings", () => ({
  useTerminalSettings: () => ({ settings: { fontSize: 13, theme: { background: "#282c34" } } }),
}));

type ResizeRecord = {
  callback: ResizeObserverCallback;
  observe: ReturnType<typeof vi.fn>;
  disconnect: ReturnType<typeof vi.fn>;
};

const resizeRecords: ResizeRecord[] = [];

class TestResizeObserver {
  readonly observe = vi.fn();
  readonly unobserve = vi.fn();
  readonly disconnect = vi.fn();

  constructor(readonly callback: ResizeObserverCallback) {
    resizeRecords.push({ callback, observe: this.observe, disconnect: this.disconnect });
  }
}

function session(): TerminalSession {
  return {
    id: "session-new",
    cwd: "/repo/main",
    workspaceId: "ws-main",
    worktree: { wsId: "ws-main", slug: "main" },
    backendSessionId: "backend-new",
    lifecycle: "working",
  };
}

describe("TerminalPane mounted sizing", () => {
  beforeEach(() => {
    manager.applySettings.mockReset();
    manager.updateSession.mockReset();
    manager.getOrCreate.mockReset();
    manager.getInstance.mockReset();
    resizeRecords.length = 0;
    vi.stubGlobal("ResizeObserver", TestResizeObserver);
  });

  afterEach(() => {
    cleanup();
    vi.unstubAllGlobals();
  });

  it("waits for a measurable mounted container and then fits the new terminal to the full pane", async () => {
    const element = document.createElement("div");
    element.className = "terminal-host";
    const fit = vi.fn();
    const focus = vi.fn();
    const instance = {
      element,
      fitAddon: { fit },
      terminal: { focus },
      active: true,
      session: session(),
    };
    manager.getOrCreate.mockResolvedValue(instance);
    manager.getInstance.mockReturnValue(instance);

    render(<TerminalPane session={session()} active />);
    const mount = screen.getByTestId("terminal-mount");
    let width = 0;
    let height = 0;
    vi.spyOn(mount, "getBoundingClientRect").mockImplementation(
      () =>
        ({
          left: 0,
          top: 0,
          right: width,
          bottom: height,
          width,
          height,
          x: 0,
          y: 0,
          toJSON: () => ({}),
        }) as DOMRect,
    );

    await waitFor(() => expect(manager.getOrCreate).toHaveBeenCalledOnce());
    await waitFor(() => expect(resizeRecords).toHaveLength(1));
    expect(resizeRecords[0].observe).toHaveBeenCalledWith(mount);
    expect(element.parentElement).toBe(mount);
    expect(fit).not.toHaveBeenCalled();

    width = 960;
    height = 640;
    act(() => {
      resizeRecords[0].callback([], {} as ResizeObserver);
    });

    await waitFor(() => expect(fit).toHaveBeenCalled());
    expect(element.style.position).toBe("absolute");
    expect(element.style.inset).toBe("0px");
    expect(element.style.width).toBe("100%");
    expect(element.style.height).toBe("100%");
    expect(element.style.minWidth).toBe("0px");
    expect(element.style.minHeight).toBe("0px");
  });

  it("fills unused terminal rows with the active terminal theme background", () => {
    manager.getOrCreate.mockResolvedValue({
      element: document.createElement("div"),
      fitAddon: { fit: vi.fn() },
      terminal: { focus: vi.fn() },
      active: true,
      session: session(),
    });

    render(<TerminalPane session={session()} active />);

    expect(screen.getByTestId("terminal-pane-surface")).toHaveStyle({ backgroundColor: "#282c34" });
    expect(screen.getByTestId("terminal-mount")).toHaveStyle({ backgroundColor: "#282c34" });
  });
});

import type { FitAddon } from "@xterm/addon-fit";
import type { SearchAddon } from "@xterm/addon-search";
import type { Terminal } from "@xterm/xterm";

import { isTauriRuntime, resizeTerminal, writeTerminal } from "./tauri";
import { terminalEventBus } from "./terminalEvents";
import { attachWebglRenderer, loadTerminalAssets } from "./terminalRenderer";
import {
  applyTerminalSettings,
  FALLBACK_PREFERENCES,
  fetchCachedNativePreferences,
  loadTerminalSettings,
  resolveTerminalSettings,
  type EffectiveTerminalSettings,
} from "./terminalSettings";
import type { TerminalSession } from "./types";

export type TerminalInstance = {
  element: HTMLDivElement;
  terminal: Terminal;
  fitAddon: FitAddon;
  searchAddon: SearchAddon;
  disposeWebgl: () => void;
  resizeObserver: ResizeObserver;
  disposables: Array<() => void>;
  session: TerminalSession;
  active: boolean;
  onBell?: () => void;
  onTitleChange?: (title: string) => void;
  unsubscribeOutput?: () => void;
};

class TerminalHostManager {
  private instances = new Map<string, TerminalInstance>();
  private pendingSpawns = new Map<string, Promise<TerminalInstance>>();

  getInstance(sessionId: string): TerminalInstance | undefined {
    return this.instances.get(sessionId);
  }

  async getOrCreate(
    session: TerminalSession,
    active: boolean,
    onBell?: () => void,
    onTitleChange?: (title: string) => void,
  ): Promise<TerminalInstance> {
    const existing = this.instances.get(session.id);
    if (existing) {
      existing.session = session;
      existing.active = active;
      existing.onBell = onBell;
      existing.onTitleChange = onTitleChange;
      return existing;
    }

    const pending = this.pendingSpawns.get(session.id);
    if (pending) return pending;

    const spawnPromise = this.createInstance(session, active, onBell, onTitleChange);
    this.pendingSpawns.set(session.id, spawnPromise);

    try {
      const instance = await spawnPromise;
      this.instances.set(session.id, instance);
      return instance;
    } finally {
      this.pendingSpawns.delete(session.id);
    }
  }

  private async createInstance(
    session: TerminalSession,
    active: boolean,
    onBell?: () => void,
    onTitleChange?: (title: string) => void,
  ): Promise<TerminalInstance> {
    const hostElement = document.createElement("div");
    hostElement.className = "terminal-host h-full w-full bg-terminal";
    hostElement.setAttribute("aria-label", `Terminal in ${session.cwd}`);

    const [latestNativePrefs, { Terminal: TerminalConstructor, FitAddon: FitAddonConstructor, Unicode11Addon, SearchAddon: SearchAddonConstructor }] =
      await Promise.all([
        Promise.race([
          fetchCachedNativePreferences(),
          new Promise<typeof FALLBACK_PREFERENCES>((resolve) =>
            setTimeout(() => resolve(FALLBACK_PREFERENCES), 200),
          ),
        ]),
        loadTerminalAssets(),
      ]);

    const finalSettings = resolveTerminalSettings(loadTerminalSettings(), latestNativePrefs);

    const terminal = new TerminalConstructor({
      allowProposedApi: false,
      customGlyphs: false,
      convertEol: true,
      cursorBlink: true,
      cursorStyle: finalSettings.cursorStyle ?? "block",
      fontFamily: finalSettings.fontFamily,
      fontSize: finalSettings.fontSize,
      lineHeight: 1.0,
      letterSpacing: 0,
      macOptionIsMeta: finalSettings.macosOptionAsAlt,
      scrollback: finalSettings.scrollback,
      theme: finalSettings.theme,
    });
    const fitAddon = new FitAddonConstructor();
    terminal.loadAddon(fitAddon);
    const searchAddon = new SearchAddonConstructor();
    terminal.loadAddon(searchAddon);
    if (Unicode11Addon) {
      try {
        const unicode11Addon = new Unicode11Addon();
        terminal.loadAddon(unicode11Addon);
        terminal.unicode.activeVersion = "11";
      } catch {
      }
    }
    terminal.open(hostElement);

    let disposeWebgl: () => void = () => undefined;
    void attachWebglRenderer(terminal).then((dispose) => {
      disposeWebgl = dispose;
    });

    let resizeFrame = 0;
    const resize = () => {
      cancelAnimationFrame(resizeFrame);
      resizeFrame = requestAnimationFrame(() => {
        if (hostElement.clientWidth === 0 || hostElement.clientHeight === 0) return;
        fitAddon.fit();
        const backendSessionId = session.backendSessionId;
        if (!backendSessionId) return;
        void resizeTerminal({ sessionId: backendSessionId, cols: terminal.cols, rows: terminal.rows }).catch(() => undefined);
      });
    };

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(hostElement);

    const disposables: Array<() => void> = [];

    const dataDisposable = terminal.onData((data) => {
      const backendSessionId = session.backendSessionId;
      if (!backendSessionId) return;
      void writeTerminal({ sessionId: backendSessionId, data }).catch(() => undefined);
    });
    disposables.push(() => dataDisposable.dispose());

    const titleDisposable = terminal.onTitleChange((title) => {
      this.instances.get(session.id)?.onTitleChange?.(title);
    });
    disposables.push(() => titleDisposable.dispose());

    const bellDisposable = terminal.onBell(() => {
      this.instances.get(session.id)?.onBell?.();
    });
    disposables.push(() => bellDisposable.dispose());

    const focusTerminal = () => terminal.focus();
    hostElement.addEventListener("pointerdown", focusTerminal);
    disposables.push(() => hostElement.removeEventListener("pointerdown", focusTerminal));

    let unsubscribeOutput: (() => void) | undefined;
    if (session.backendSessionId) {
      unsubscribeOutput = terminalEventBus.subscribeOutput(session.backendSessionId, (text) => {
        terminal.write(text);
      });
    }

    if (!isTauriRuntime()) {
      terminal.writeln("\x1b[1;32mFerryx\x1b[0m  UI preview");
      terminal.writeln("\x1b[90mLaunch through Tauri to attach the PTY session.\x1b[0m");
      terminal.write("\r\n\x1b[34m~\x1b[0m \x1b[32m❯\x1b[0m ");
    }

    resize();
    if (active) terminal.focus();

    return {
      element: hostElement,
      terminal,
      fitAddon,
      searchAddon,
      disposeWebgl,
      resizeObserver,
      disposables,
      session,
      active,
      onBell,
      onTitleChange,
      unsubscribeOutput,
    };
  }

  updateSession(sessionId: string, session: TerminalSession) {
    const inst = this.instances.get(sessionId);
    if (inst) {
      const prevBackendId = inst.session.backendSessionId;
      inst.session = session;
      if (session.backendSessionId !== prevBackendId) {
        inst.unsubscribeOutput?.();
        inst.unsubscribeOutput = undefined;
        if (session.backendSessionId) {
          inst.unsubscribeOutput = terminalEventBus.subscribeOutput(session.backendSessionId, (text) => {
            inst.terminal.write(text);
          });
        }
      }
    }
  }

  applySettings(settings: EffectiveTerminalSettings) {
    for (const inst of this.instances.values()) {
      applyTerminalSettings(inst.terminal, settings);
      inst.fitAddon.fit();
    }
  }

  destroy(sessionId: string) {
    const inst = this.instances.get(sessionId);
    if (inst) {
      this.instances.delete(sessionId);
      inst.resizeObserver.disconnect();
      inst.unsubscribeOutput?.();
      for (const d of inst.disposables) d();
      inst.searchAddon.dispose();
      inst.disposeWebgl();
      inst.terminal.dispose();
      inst.element.remove();
    }
  }
}

export const terminalHostManager = new TerminalHostManager();

import { DEFAULT_TERMINAL_FONT_STACK } from "./tauri";
import { useCallback, useEffect, useMemo, useState } from "react";

import { getMigratedItem, TERMINAL_SETTINGS_STORAGE_KEY } from "./storageKeys";
import { getTerminalPreferences, type TerminalPreferences, type TerminalThemeColors } from "./tauri";

export type TerminalSettings = {
  fontFamily: string | null;
  macosOptionAsAlt: boolean | null;
  fontSize: number | null;
  scrollback: number;
};

export type TerminalSettingSource = "local" | "ghostty" | "fallback";

export type EffectiveTerminalSettings = {
  fontFamily: string;
  macosOptionAsAlt: boolean;
  fontSize: number;
  scrollback: number;
  cursorStyle: "bar" | "block" | "underline";
  theme: TerminalThemeColors;
  fontFamilySource: TerminalSettingSource;
  macosOptionAsAltSource: TerminalSettingSource;
  fontSizeSource: TerminalSettingSource;
};

export type ResolvedTerminalSettings = EffectiveTerminalSettings;

export { TERMINAL_SETTINGS_STORAGE_KEY };
export const TERMINAL_BACKGROUND_STORAGE_KEY = "ferryx.terminal.background";
export const DEFAULT_TERMINAL_SETTINGS: TerminalSettings = {
  fontFamily: null,
  macosOptionAsAlt: null,
  fontSize: null,
  scrollback: 10_000,
};

const TERMINAL_SETTINGS_EVENT = "orca:terminal-settings";
const FONT_SIZE_MIN = 10;
const FONT_SIZE_MAX = 36;
const SCROLLBACK_MIN = 1_000;
const SCROLLBACK_MAX = 100_000;

export const DEFAULT_TERMINAL_THEME: TerminalThemeColors = {
  background: "#282c34",
  foreground: "#ffffff",
  cursor: "#ffffff",
  cursorAccent: "#282c34",
  selectionBackground: "#52525299",
  black: "#1d1f21",
  red: "#cc6666",
  green: "#b5bd68",
  yellow: "#f0c674",
  blue: "#81a2be",
  magenta: "#b294bb",
  cyan: "#8abeb7",
  white: "#c5c8c6",
  brightBlack: "#666666",
  brightRed: "#d54e53",
  brightGreen: "#b9ca4a",
  brightYellow: "#e7c547",
  brightBlue: "#7aa6da",
  brightMagenta: "#c397d8",
  brightCyan: "#70c0b1",
  brightWhite: "#eaeaea",
  extendedAnsi: [],
};

export const FALLBACK_PREFERENCES: TerminalPreferences = {
  fontFamily: DEFAULT_TERMINAL_FONT_STACK,
  fontSize: 13,
  macosOptionAsAlt: false,
  cursorStyle: "block",
  theme: DEFAULT_TERMINAL_THEME,
  source: "defaults",
  status: "absent",
  sourcePath: null,
};

type TerminalOptionsTarget = {
  options: {
    fontFamily?: string;
    macOptionIsMeta?: boolean;
    fontSize?: number;
    scrollback?: number;
    cursorStyle?: "bar" | "block" | "underline";
    theme?: import("@xterm/xterm").ITheme;
  };
};

export function loadTerminalSettings(storage: Pick<Storage, "getItem" | "setItem"> | null = browserStorage()): TerminalSettings {
  if (!storage) return DEFAULT_TERMINAL_SETTINGS;
  try {
    const raw = getMigratedItem(TERMINAL_SETTINGS_STORAGE_KEY, storage);
    if (!raw) return DEFAULT_TERMINAL_SETTINGS;
    return normalizeTerminalSettings(JSON.parse(raw) as Partial<TerminalSettings>);
  } catch {
    return DEFAULT_TERMINAL_SETTINGS;
  }
}

export function saveTerminalSettings(
  next: Partial<TerminalSettings>,
  storage: Pick<Storage, "setItem"> | null = browserStorage(),
): TerminalSettings {
  const normalized = normalizeTerminalSettings(next);
  try {
    storage?.setItem(TERMINAL_SETTINGS_STORAGE_KEY, JSON.stringify(normalized));
  } catch {
  }
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent<TerminalSettings>(TERMINAL_SETTINGS_EVENT, { detail: normalized }));
  }
  return normalized;
}

export function syncTerminalBackground(background: string) {
  if (typeof document !== "undefined") {
    document.documentElement.style.setProperty("--terminal", background);
    const channels = hexColorChannels(background);
    if (channels) document.documentElement.style.setProperty("--terminal-rgb", channels);
  }
  try {
    browserStorage()?.setItem(TERMINAL_BACKGROUND_STORAGE_KEY, background);
  } catch {
  }
}

export function applyCachedTerminalBackground() {
  try {
    const background = browserStorage()?.getItem(TERMINAL_BACKGROUND_STORAGE_KEY) ?? null;
    if (background && typeof document !== "undefined") {
      document.documentElement.style.setProperty("--terminal", background);
      const channels = hexColorChannels(background);
      if (channels) document.documentElement.style.setProperty("--terminal-rgb", channels);
    }
    return background;
  } catch {
    return null;
  }
}

function hexColorChannels(background: string) {
  const match = /^#([\da-f]{2})([\da-f]{2})([\da-f]{2})$/i.exec(background);
  if (!match) return null;
  return `${Number.parseInt(match[1], 16)} ${Number.parseInt(match[2], 16)} ${Number.parseInt(match[3], 16)}`;
}

export function resolveTerminalSettings(
  local: TerminalSettings,
  nativePreferences: TerminalPreferences = FALLBACK_PREFERENCES,
): EffectiveTerminalSettings {
  const ghosttyImported = nativePreferences.source === "ghostty" && nativePreferences.status === "imported";
  const localFontFamily = normalizeOptionalFontFamily(local.fontFamily);
  const hasLocalOptionOverride = typeof local.macosOptionAsAlt === "boolean";
  const hasLocalFontSizeOverride = typeof local.fontSize === "number" && Number.isFinite(local.fontSize);

  const cursorStyle: "bar" | "block" | "underline" =
    nativePreferences.cursorStyle === "bar" || nativePreferences.cursorStyle === "underline"
      ? nativePreferences.cursorStyle
      : "block";

  const effectiveFontSize = hasLocalFontSizeOverride
    ? local.fontSize!
    : nativePreferences.fontSize ?? 13;

  return {
    fontFamily: localFontFamily ?? (nativePreferences.fontFamily || DEFAULT_TERMINAL_FONT_STACK),
    macosOptionAsAlt: hasLocalOptionOverride ? local.macosOptionAsAlt! : nativePreferences.macosOptionAsAlt,
    fontSize: effectiveFontSize,
    scrollback: local.scrollback,
    cursorStyle,
    theme: nativePreferences.theme ?? DEFAULT_TERMINAL_THEME,
    fontFamilySource: localFontFamily ? "local" : ghosttyImported ? "ghostty" : "fallback",
    macosOptionAsAltSource: hasLocalOptionOverride ? "local" : ghosttyImported ? "ghostty" : "fallback",
    fontSizeSource: hasLocalFontSizeOverride ? "local" : ghosttyImported ? "ghostty" : "fallback",
  };
}

export function applyTerminalSettings(terminal: TerminalOptionsTarget, settings: EffectiveTerminalSettings) {
  terminal.options.fontFamily = settings.fontFamily;
  terminal.options.macOptionIsMeta = settings.macosOptionAsAlt;
  terminal.options.fontSize = settings.fontSize;
  terminal.options.scrollback = settings.scrollback;
  terminal.options.cursorStyle = settings.cursorStyle;
  terminal.options.theme = {
    background: settings.theme.background,
    foreground: settings.theme.foreground,
    cursor: settings.theme.cursor,
    cursorAccent: settings.theme.cursorAccent,
    selectionBackground: settings.theme.selectionBackground,
    selectionForeground: settings.theme.selectionForeground,
    black: settings.theme.black,
    red: settings.theme.red,
    green: settings.theme.green,
    yellow: settings.theme.yellow,
    blue: settings.theme.blue,
    magenta: settings.theme.magenta,
    cyan: settings.theme.cyan,
    white: settings.theme.white,
    brightBlack: settings.theme.brightBlack,
    brightRed: settings.theme.brightRed,
    brightGreen: settings.theme.brightGreen,
    brightYellow: settings.theme.brightYellow,
    brightBlue: settings.theme.brightBlue,
    brightMagenta: settings.theme.brightMagenta,
    brightCyan: settings.theme.brightCyan,
    brightWhite: settings.theme.brightWhite,
    extendedAnsi: settings.theme.extendedAnsi,
  };
}

let globalPreferencesPromise: Promise<TerminalPreferences> | null = null;

export function resetTerminalPreferencesCache() {
  globalPreferencesPromise = null;
}

export async function fetchCachedNativePreferences(force = false): Promise<TerminalPreferences> {
  if (!globalPreferencesPromise || force) {
    try {
      const promise = getTerminalPreferences();
      globalPreferencesPromise =
        promise && typeof promise.catch === "function"
          ? promise.catch(() => FALLBACK_PREFERENCES)
          : Promise.resolve(FALLBACK_PREFERENCES);
    } catch {
      globalPreferencesPromise = Promise.resolve(FALLBACK_PREFERENCES);
    }
  }
  return globalPreferencesPromise;
}

export function useTerminalSettings() {
  const [localSettings, setLocalSettings] = useState<TerminalSettings>(() => loadTerminalSettings());
  const [nativePreferences, setNativePreferences] = useState<TerminalPreferences>(FALLBACK_PREFERENCES);

  const refreshNativePreferences = useCallback(async (force = true): Promise<TerminalPreferences> => {
    const preferences = await fetchCachedNativePreferences(force);
    setNativePreferences(preferences);
    return preferences;
  }, []);

  useEffect(() => {
    void refreshNativePreferences(true);
  }, [refreshNativePreferences]);

  useEffect(() => {
    const handleSettings = (event: Event) => {
      const detail = (event as CustomEvent<TerminalSettings>).detail;
      if (detail) setLocalSettings(normalizeTerminalSettings(detail));
    };
    const handleStorage = (event: StorageEvent) => {
      if (event.key === TERMINAL_SETTINGS_STORAGE_KEY) setLocalSettings(loadTerminalSettings());
    };
    window.addEventListener(TERMINAL_SETTINGS_EVENT, handleSettings);
    window.addEventListener("storage", handleStorage);
    return () => {
      window.removeEventListener(TERMINAL_SETTINGS_EVENT, handleSettings);
      window.removeEventListener("storage", handleStorage);
    };
  }, []);

  const updateSettings = useCallback((patch: Partial<TerminalSettings>) => {
    setLocalSettings((current) => saveTerminalSettings({ ...current, ...patch }));
  }, []);

  const settings = useMemo(
    () => resolveTerminalSettings(localSettings, nativePreferences),
    [localSettings, nativePreferences],
  );

  useEffect(() => {
    syncTerminalBackground(settings.theme.background);
  }, [settings.theme.background]);

  return { settings, localSettings, nativePreferences, updateSettings, refreshNativePreferences };
}

function normalizeTerminalSettings(settings: Partial<TerminalSettings>): TerminalSettings {
  return {
    fontFamily: normalizeOptionalFontFamily(settings.fontFamily),
    macosOptionAsAlt: typeof settings.macosOptionAsAlt === "boolean" ? settings.macosOptionAsAlt : null,
    fontSize: typeof settings.fontSize === "number" && Number.isFinite(settings.fontSize)
      ? clampInteger(settings.fontSize, 13, FONT_SIZE_MIN, FONT_SIZE_MAX)
      : null,
    scrollback: clampInteger(settings.scrollback, DEFAULT_TERMINAL_SETTINGS.scrollback, SCROLLBACK_MIN, SCROLLBACK_MAX),
  };
}

function normalizeOptionalFontFamily(value: string | null | undefined) {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

function clampInteger(value: number | undefined, fallback: number, min: number, max: number) {
  if (!Number.isFinite(value)) return fallback;
  return Math.min(max, Math.max(min, Math.round(value!)));
}

function browserStorage() {
  if (typeof window === "undefined") return null;
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

